<template><div class="resource-page"><ResourceHeader title="首页模板" description="后台直接维护模板目录，发布后客户端可按应用获取。" action-text="添加托管模板" @action="openCreate" /><ElCard shadow="never" class="table-card" v-loading="loading"><div v-if="!templates.length && !loading" class="empty"><ArtSvgIcon icon="ri:layout-4-line" /><strong>还没有托管模板</strong><span>填写模板 JSON 或 ZIP 的公开地址即可发布。</span><ElButton type="primary" @click="openCreate">添加托管模板</ElButton></div><div v-for="item in templates" :key="item.id" class="template-row"><div :class="['preview', tone(item.id)]"><strong>{{ item.name.slice(0,1) }}</strong></div><div class="info"><b>{{ item.name }}</b><span>{{ item.templateId }} · v{{ item.version }} · Schema {{ item.schemaVersion || 1 }}</span><small>{{ item.contentUrl }}</small></div><ElTag :type="item.published ? 'success' : 'info'" effect="light">{{ item.published ? '已发布' : '已下线' }}</ElTag><ElButton link type="primary" @click="edit(item)">编辑</ElButton><ElButton link type="danger" @click="remove(item)">删除</ElButton></div></ElCard><ElDialog v-model="dialog" :title="editing ? '编辑托管模板' : '添加托管模板'" width="540px"><ElForm :model="form" label-position="top"><ElFormItem label="模板标识"><ElInput v-model="form.templateId" placeholder="例如 aurora-home" /></ElFormItem><ElFormItem label="模板名称"><ElInput v-model="form.name" /></ElFormItem><ElFormItem label="模板内容地址"><ElInput v-model="form.contentUrl" placeholder="https://.../template.json 或 template.zip" /></ElFormItem><ElFormItem label="预览图地址"><ElInput v-model="form.previewUrl" /></ElFormItem><ElFormItem label="版本"><ElInput v-model="form.version" /></ElFormItem><ElFormItem label="SHA-256（可选）"><ElInput v-model="form.sha256" /></ElFormItem><ElFormItem label="简介"><ElInput v-model="form.description" type="textarea" /></ElFormItem></ElForm><template #footer><ElButton @click="dialog=false">取消</ElButton><ElButton type="primary" :loading="saving" @click="save">保存并发布</ElButton></template></ElDialog></div></template>
<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import ResourceHeader from '@/components/plus-resource/ResourceHeader.vue';import {deleteManagedTemplate,fetchManagedTemplates,saveManagedTemplate,type ManagedTemplateItem} from '@/api/system-manage';const loading=ref(false);const saving=ref(false);const dialog=ref(false);const editing=ref(false);const editingId=ref(0);const templates=ref<ManagedTemplateItem[]>([]);const form=reactive({templateId:'',name:'',contentUrl:'',previewUrl:'',version:'1.0.0',sha256:'',description:''});const tone=(id:number)=>['aurora','midnight','minimal'][id%3];const load=async()=>{loading.value=true;try{templates.value=(await fetchManagedTemplates()).list||[]}catch(e:any){ElMessage.error(e?.message||'模板加载失败')}finally{loading.value=false}};const reset=()=>Object.assign(form,{templateId:'',name:'',contentUrl:'',previewUrl:'',version:'1.0.0',sha256:'',description:''});const openCreate=()=>{editing.value=false;editingId.value=0;reset();dialog.value=true};const edit=(item:ManagedTemplateItem)=>{editing.value=true;editingId.value=item.id;Object.assign(form,item);dialog.value=true};const save=async()=>{if(!form.templateId||!form.name||!form.contentUrl){ElMessage.warning('请填写模板标识、名称和内容地址');return};saving.value=true;try{await saveManagedTemplate({...form,id:editing.value?editingId.value:undefined,schemaVersion:1,published:true});ElMessage.success('模板已保存');dialog.value=false;await load()}catch(e:any){ElMessage.error(e?.message||'保存模板失败')}finally{saving.value=false}};const remove=async(item:ManagedTemplateItem)=>{try{await ElMessageBox.confirm(`确认删除模板「${item.name}」？`,'删除模板',{type:'warning'});await deleteManagedTemplate(item.id);ElMessage.success('模板已删除');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e?.message||'删除模板失败')}};onMounted(load)</script>
<style scoped>.resource-page{padding:24px;background:#f6f8fc;min-height:100%;color:#172033}.table-card{margin-top:18px;border:0;border-radius:14px}.template-row{display:flex;align-items:center;gap:14px;padding:16px 4px;border-bottom:1px solid #edf0f5}.template-row:last-child{border-bottom:0}.preview{display:grid;place-items:center;flex:0 0 54px;width:54px;height:54px;border-radius:12px;color:#fff;font-size:25px}.aurora{background:linear-gradient(140deg,#7162d4,#d78fb1)}.midnight{background:linear-gradient(140deg,#17233e,#3d6791)}.minimal{background:linear-gradient(140deg,#cbd3df,#f4b38e)}.info{display:flex;flex:1;min-width:0;flex-direction:column;gap:5px}.info span,.info small{overflow:hidden;color:#8b94a5;font-size:11px;text-overflow:ellipsis;white-space:nowrap}.empty{display:flex;align-items:center;flex-direction:column;gap:10px;padding:36px;color:#8b94a5;text-align:center}.empty>svg{font-size:34px;color:#7354c8}.empty strong{color:#172033}@media(max-width:700px){.resource-page{padding:12px}.template-row{align-items:flex-start;flex-wrap:wrap}.info{min-width:calc(100% - 70px)}.template-row .el-button{margin-left:68px}}
</style>
